//! Real-ESRGAN in Burn: the models generated by build.rs, `upscale_rgb`,
//! which cuts an image into same-sized tiles for them and back, and
//! `Upscaler`, which the pool app runs a job with (an image file in, a JPEG out).

pub mod model {
    pub mod real_esrgan_general_x4v3 {
        include!(concat!(env!("OUT_DIR"), "/model/real_esrgan_general_x4v3.rs"));
    }
    pub mod real_esrgan_x4plus {
        include!(concat!(env!("OUT_DIR"), "/model/real_esrgan_x4plus.rs"));
    }
}

use burn::prelude::*;

/// Every model here enlarges 4×.
pub const SCALE: usize = 4;

/// Upscales an RGB image (8-bit, row by row) 4× by running `forward` on tiles
/// of `tile` px, each read with `pad` px of its neighbours so the seams don't
/// show, and returns the RGB bytes of the result. Every call to `forward` gets
/// the same shape, (tile + 2 × pad) square, with edge pixels repeated past the
/// border: the GPU kernels are compiled and tuned once, not per tile size.
pub fn upscale_rgb(
    rgb: &[u8],
    width: usize,
    height: usize,
    tile: usize,
    pad: usize,
    device: &Device,
    forward: impl Fn(Tensor<4>) -> Tensor<4>,
) -> Vec<u8> {
    let ow = width * SCALE;
    let side = tile + 2 * pad;
    let mut out = vec![0u8; ow * height * SCALE * 3];
    let mut planar = vec![0f32; 3 * side * side];
    for ty in (0..height).step_by(tile) {
        for tx in (0..width).step_by(tile) {
            // The area around the tile, as a 1×3×side×side tensor in 0..1.
            for y in 0..side {
                let sy = (ty + y).saturating_sub(pad).min(height - 1);
                for x in 0..side {
                    let sx = (tx + x).saturating_sub(pad).min(width - 1);
                    let i = (sy * width + sx) * 3;
                    for c in 0..3 {
                        planar[c * side * side + y * side + x] = rgb[i + c] as f32 / 255.0;
                    }
                }
            }
            let input = Tensor::<4>::from_data(TensorData::new(planar.clone(), [1, 3, side, side]), device);
            let result: Vec<f32> = forward(input).into_data().try_to_vec::<f32>().expect("f32 output");
            // Copy back only the tile itself, which starts pad px in.
            let s = side * SCALE;
            let (ox, oy) = (pad * SCALE, pad * SCALE);
            let (tw, th) = ((tx + tile).min(width) - tx, (ty + tile).min(height) - ty);
            for y in 0..th * SCALE {
                for x in 0..tw * SCALE {
                    let o = ((ty * SCALE + y) * ow + tx * SCALE + x) * 3;
                    for c in 0..3 {
                        let v = result[c * s * s + (oy + y) * s + ox + x];
                        out[o + c] = (v.clamp(0.0, 1.0) * 255.0).round() as u8;
                    }
                }
            }
        }
    }
    out
}

// ---- for the pool app: one loaded model, image files in and out ----------------

/// The largest picture taken in, in pixels (640 × 640): the result is 16 times
/// that, and travels back to the pool as one message.
pub const MAX_PIXELS: u64 = 640 * 640;
const TILE: usize = 112; // + 2 × PAD = 128 px, the fastest measured (plans/local-images.md)
const PAD: usize = 8;
const QUALITY_FILE: &str = "real_esrgan_x4plus.bpk";

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Kind {
    Fast,
    Quality,
}

impl Kind {
    /// The pool's name for it.
    pub fn name(self) -> &'static str {
        match self {
            Kind::Fast => "upscale-fast",
            Kind::Quality => "upscale-quality",
        }
    }
    pub fn from_name(name: &str) -> Option<Kind> {
        [Kind::Fast, Kind::Quality].into_iter().find(|k| k.name() == name)
    }
}

/// Where the quality model's weights are, if anywhere: next to the program's
/// own data (`dir`), or where this build wrote them (a developer's machine).
pub fn quality_weights(dir: Option<&std::path::Path>) -> Option<std::path::PathBuf> {
    let built = std::path::PathBuf::from(concat!(env!("OUT_DIR"), "/model/real_esrgan_x4plus.bpk"));
    dir.map(|d| d.join(QUALITY_FILE)).into_iter().chain([built]).find(|p| p.is_file())
}

/// The models this machine can run: fast always, quality when its file is here.
pub fn available(dir: Option<&std::path::Path>) -> Vec<Kind> {
    let mut kinds = vec![Kind::Fast];
    if quality_weights(dir).is_some() {
        kinds.push(Kind::Quality);
    }
    kinds
}

type Forward = Box<dyn Fn(Tensor<4>) -> Tensor<4> + Send>;

/// One model, loaded on the graphics chip. The first picture also compiles
/// and tunes the chip's code for the tile (3–6 s on an M2 Pro).
pub struct Upscaler {
    pub kind: Kind,
    device: Device,
    forward: Forward,
}

impl Upscaler {
    pub fn load(kind: Kind, dir: Option<&std::path::Path>) -> Result<Upscaler, String> {
        let device = Device::default();
        let forward: Forward = match kind {
            Kind::Fast => {
                let m = model::real_esrgan_general_x4v3::Model::from_embedded(&device);
                Box::new(move |x| m.forward(x))
            }
            Kind::Quality => {
                let path = quality_weights(dir).ok_or("the quality model is not on this computer")?;
                let m = model::real_esrgan_x4plus::Model::from_file(path, &device);
                Box::new(move |x| m.forward(x))
            }
        };
        Ok(Upscaler { kind, device, forward })
    }

    /// A PNG, JPEG or WebP file in, a JPEG 4× its size out, with that size.
    pub fn file(&self, bytes: &[u8]) -> Result<(Vec<u8>, u32, u32), String> {
        let img = image::load_from_memory(bytes).map_err(|e| format!("not a picture: {e}"))?.to_rgb8();
        let (w, h) = (img.width(), img.height());
        if w as u64 * h as u64 > MAX_PIXELS {
            return Err(format!("{w}×{h} is too big: at most {} pixels", MAX_PIXELS));
        }
        let rgb = upscale_rgb(img.as_raw(), w as usize, h as usize, TILE, PAD, &self.device, &self.forward);
        let (ow, oh) = (w * SCALE as u32, h * SCALE as u32);
        let mut out = Vec::new();
        image::codecs::jpeg::JpegEncoder::new_with_quality(&mut out, 90)
            .encode(&rgb, ow, oh, image::ExtendedColorType::Rgb8)
            .map_err(|e| e.to_string())?;
        Ok((out, ow, oh))
    }
}
